// Configuration
var token = input.get("accessToken");
var maxPages = parseInt(input.get("maxPages")) || 100;
var pageSize = parseInt(input.get("pageSize")) || 100;
var selectFields = input.get("selectFields") || "";

// Validate token
if (!token) {
    log.error("Access token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access token is required");
    tags.trigger("error");
} else {
    // Initialize
    var allUsers = [];
    var pagesProcessed = 0;
    var hasErrors = false;
    var errorMessage = "";

    // Build initial URL
    var nextUrl = "https://graph.microsoft.com/v1.0/users?$top=" + pageSize;
    if (selectFields) {
        nextUrl += "&$select=" + selectFields;
    }

    // Headers for Graph API
    var headers = {
        "Authorization": "Bearer " + token,
        "Accept": "application/json",
        "ConsistencyLevel": "eventual"
    };

    log.info("Starting Graph users fetch, max pages: " + maxPages);

    // Pagination loop
    while (nextUrl && pagesProcessed < maxPages) {
        pagesProcessed++;
        log.debug("Fetching page " + pagesProcessed + ": " + nextUrl);

        try {
            var response = http.get(nextUrl, headers);

            if (!response.isSuccess) {
                hasErrors = true;
                errorMessage = "API error on page " + pagesProcessed + ": HTTP " + response.statusCode;
                log.error(errorMessage);
                break;
            }

            var data = json.parse(response.body);

            // Extract users from response
            if (data && data.value && Array.isArray(data.value)) {
                for (var i = 0; i < data.value.length; i++) {
                    allUsers.push(data.value[i]);
                }
                log.info("Page " + pagesProcessed + ": Retrieved " + data.value.length + " users");
            }

            // Check for next page (OData uses @odata.nextLink)
            if (data && data["@odata.nextLink"]) {
                nextUrl = data["@odata.nextLink"];
            } else {
                nextUrl = null;
            }

        } catch (ex) {
            hasErrors = true;
            errorMessage = "Exception on page " + pagesProcessed + ": " + ex.message;
            log.error(errorMessage);
            break;
        }
    }

    // Set outputs
    output.set("Users", allUsers);
    output.setJson("UsersJson", allUsers);
    output.set("TotalCount", allUsers.length);
    output.set("PagesProcessed", pagesProcessed);
    output.set("HasErrors", hasErrors);
    output.set("ErrorMessage", errorMessage);

    log.info("Completed: " + allUsers.length + " users in " + pagesProcessed + " pages");

    // Trigger appropriate connection tag
    if (hasErrors) {
        tags.trigger("error");
    } else if (allUsers.length === 0) {
        tags.trigger("empty");
    } else {
        tags.trigger("success");
    }
}
